const b = $input.first().json.body ?? {};
const message = typeof b.message === 'string' ? b.message.trim() : '';
const sessionId = typeof b.sessionId === 'string' && /^[a-zA-Z0-9_-]{8,128}$/.test(b.sessionId) ? b.sessionId : '';
const history = Array.isArray(b.history) ? b.history.slice(-6).filter(x => x && ['user','assistant'].includes(x.role) && typeof x.content === 'string').map(x => ({role:x.role,content:x.content.slice(0,1000)})) : [];
const inputCatalog = b.context?.catalog;
function short(v,max=160){ return typeof v === 'string' ? v.slice(0,max) : ''; }
function number(v){ if(v===null||v===undefined||v===''||typeof v==='boolean')return null; const n=Number(v); return Number.isFinite(n) && n>=0 && n<=1000000000 ? n : null; }
function asArray(value){return Array.isArray(value) ? value : []}
const tours = asArray(inputCatalog?.tours).slice(0,80).map(t=>({
 id:short(t.id,80),title:short(t.title,150),destination:short(t.destination,100),
 days:number(t.days),cost:number(t.cost),carbon:number(t.carbon),description:short(t.description,240),
 rating:number(t.rating),url:short(t.url,250),tags:asArray(t.tags).slice(0,6).map(x=>short(x,40))
})).filter(t=>t.id&&t.title);
const services = asArray(inputCatalog?.services).slice(0,80).map(s=>({
 id:short(s.id,80),name:short(s.name,150),type:short(s.type,40),destination:short(s.destination,100),
 cost:number(s.cost),carbon:number(s.carbon),rating:number(s.rating),status:short(s.status,40),url:short(s.url,250)
})).filter(s=>s.id&&s.name&&['active','approved','published','available'].includes(s.status.toLowerCase()));
const normalizedIntentMessage=message.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\u0111\u0110]/g,'d').toLowerCase();
function classifyIntent(value){
 const normalized=String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\u0111\u0110]/g,'d').toLowerCase();
 if(/backend intent: custom_itinerary/.test(normalized))return 'itinerary';
 const hasPlanAction=/\b(?:lap|tao|len|xay dung|thiet ke|lam|sap xep|soan)\b/.test(normalized);
 const mentionsPlan=/\b(?:lich(?: trinh| di)?|hanh trinh|ke hoach(?: du lich| chuyen di)?)\b/.test(normalized)||(hasPlanAction&&/\btour\b/.test(normalized));
 const asksForPlan=/\b(?:goi y|de xuat|tu van|muon)\b/.test(normalized);
 const explicitTourSearch=/\btour\b/.test(normalized)&&/\b(?:tim|goi y|de xuat|so sanh|chon|tu van|muon)\b/.test(normalized);
 if(mentionsPlan&&(hasPlanAction||(asksForPlan&&!explicitTourSearch)))return 'itinerary';
 return explicitTourSearch?'tour_search':'';
}
const currentIntent=classifyIntent(message);
const latestHistoryIntent=[...history].reverse().filter(item=>item.role==='user').map(item=>classifyIntent(item.content)).find(Boolean)||'';
const lastAssistantText=[...history].reverse().find(item=>item.role==='assistant')?.content||'';
const normalizedAssistantText=String(lastAssistantText).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\u0111\u0110]/g,'d').toLowerCase();
const answersDuration=/\b\d{1,2}\s*(?:ngay|day|dem|night)\b/.test(normalizedIntentMessage);
const answersItineraryClarification=/ban muon di (?:.{1,50} )?(?:trong bao lau|bao nhieu ngay)|ban muon lap lich trinh o dau|ban muon den diem den nao|chon mot diem den|chon thoi luong/.test(normalizedAssistantText);
const itineraryContinuation=latestHistoryIntent==='itinerary'&&(answersDuration||answersItineraryClarification);
const requestIntent=b.requestIntent==='itinerary'||currentIntent==='itinerary'||itineraryContinuation?'itinerary':b.requestIntent==='tour_search'||currentIntent==='tour_search'?'tour_search':'general';
const valid = message.length>0 && message.length<=4000 && !!sessionId;
return [{json:{valid,message,requestIntent,sessionId,history,
 catalog:{tours,services,available:inputCatalog?.available===true,
 fetchedAt:short(inputCatalog?.fetchedAt,40),truncated:inputCatalog?.truncated===true},
 error:valid?'':(!sessionId?'sessionId phải có 8-128 ký tự a-z A-Z 0-9 _ -':'message phải dài từ 1 đến 4000 ký tự')}}];

const ai=$input.first().json;
const input=$('Validate Input').first().json;
const agentMs=Math.max(0,Date.now()-$('AI Start').first().json._aiStartedAt);
let output=typeof ai.output==='string'?ai.output.trim():'';
const iterationLimited=/^Agent stopped due to max iterations\.?$/i.test(output);
if(iterationLimited) output='';
const reason=ai.finishReason ?? ai.response_metadata?.finishReason;
const outputLimited=reason==='MAX_TOKENS';
if(outputLimited && output) output+='\n\n_Lượt trả lời đã chạm giới hạn độ dài. Bạn có thể yêu cầu viết tiếp phần còn thiếu._';
console.log(JSON.stringify({event:'greensteps_n8n_agent_performance',agentMs,success:!!output}));
return [{json:{success:!!output,output,...(iterationLimited?{code:'CHAT_ITERATION_LIMIT'}:{}),sessionId:input.sessionId,mode:'n8n-gemini-agent-v3',outputLimited,performance:{agentMs}}}];

const toolStarted=Date.now();
try { return (()=>{
const data=$('Validate Input').first().json;
const args=typeof query==='object'&&query!==null?query:(()=>{try{return JSON.parse(query)}catch{return {search:String(query||'')}}})();
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const catalog=data.catalog;
if(!catalog.available)return JSON.stringify({status:'catalog_unavailable',message:'Backend chưa gửi danh mục GreenSteps.'});
const q=norm(args.search||'');
const max=Number(args.maxBudget),days=Number(args.days);
const r=catalog.tours.filter(t=>(!q||norm(t.title+' '+t.destination+' '+t.description).includes(q))&&(!Number.isFinite(max)||max<=0||t.cost===null||t.cost<=max)&&(!Number.isFinite(days)||days<=0||t.days===days)).slice(0,8);
return JSON.stringify({status:'ok',matches:r,listedOnly:true,truncated:catalog.truncated,fetchedAt:catalog.fetchedAt});
})(); } finally { console.log(JSON.stringify({event:'greensteps_n8n_tool_performance',tool:"search_tours",durationMs:Date.now()-toolStarted})); }

const toolStarted=Date.now();
try { return (()=>{
const data=$('Validate Input').first().json;
const args=typeof query==='object'&&query!==null?query:(()=>{try{return JSON.parse(query)}catch{return {search:String(query||'')}}})();
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const catalog=data.catalog;
if(!catalog.available)return JSON.stringify({status:'catalog_unavailable',message:'Backend chưa gửi danh mục GreenSteps.'});
const q=norm(args.search||''),d=norm(args.destination||''),typ=norm(args.type||'');
const max=Number(args.maxBudget);
const r=catalog.services.filter(s=>(!q||norm(s.name+' '+s.destination+' '+s.type).includes(q))&&(!d||norm(s.destination).includes(d))&&(!typ||norm(s.type).includes(typ))&&(!Number.isFinite(max)||max<=0||s.cost===null||s.cost<=max)).slice(0,8);
return JSON.stringify({status:'ok',matches:r,listedOnly:true,truncated:catalog.truncated,fetchedAt:catalog.fetchedAt});
})(); } finally { console.log(JSON.stringify({event:'greensteps_n8n_tool_performance',tool:"search_services",durationMs:Date.now()-toolStarted})); }

const toolStarted=Date.now();
try { return (()=>{
const data=$('Validate Input').first().json;
const args=typeof query==='object'&&query!==null?query:(()=>{try{return JSON.parse(query)}catch{return {search:String(query||'')}}})();
const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
if(!data.catalog.available)return JSON.stringify({status:'catalog_unavailable'});
const q=norm(args.search||'');
const destinations=[...new Set([...data.catalog.tours.map(t=>t.destination),...data.catalog.services.map(s=>s.destination)].filter(Boolean))].filter(d=>!q||norm(d).includes(q)).slice(0,30);
return JSON.stringify({status:'ok',destinations,truncated:data.catalog.truncated});
})(); } finally { console.log(JSON.stringify({event:'greensteps_n8n_tool_performance',tool:"destination_inventory",durationMs:Date.now()-toolStarted})); }

const toolStarted=Date.now();
try { return (()=>{
const args=typeof query==='object'&&query!==null?query:{};
const items=Array.isArray(args.items)?args.items:[];
if(items.length===0||items.length>20)return JSON.stringify({status:'invalid_items'});
let total=0;const lines=[];
for(const i of items){const c=Number(i.unitCost),q=Number(i.quantity);
 if(i.unitCost===null||i.unitCost===undefined||i.unitCost===''||typeof i.unitCost==='boolean'||!Number.isFinite(c)||!Number.isFinite(q)||c<0||c>1000000000||q<=0||q>100||!String(i.name||'').trim())return JSON.stringify({status:'invalid_item',item:String(i.name||'')});
 const sub=Math.round(c*q);total+=sub;lines.push({name:String(i.name).slice(0,80),unitCost:c,quantity:q,subtotal:sub});}
const budget=Number(args.budget);return JSON.stringify({status:'ok',currency:'VND',items:lines,total, budget:Number.isFinite(budget)&&budget>0?budget:null,remaining:Number.isFinite(budget)&&budget>0?Math.round(budget-total):null,notice:'Chỉ là tổng các khoản đã đưa vào. Không bao gồm khoản còn thiếu.'});
})(); } finally { console.log(JSON.stringify({event:'greensteps_n8n_tool_performance',tool:"budget_estimate",durationMs:Date.now()-toolStarted})); }

const toolStarted=Date.now();
