const items=typeof query==='object'&&Array.isArray(query.items)?query.items:[];
if(!items.length||items.length>20||items.some(i=>i.kgCO2e===null||i.kgCO2e===undefined||i.kgCO2e===''||typeof i.kgCO2e==='boolean'||!Number.isFinite(Number(i.kgCO2e))||Number(i.kgCO2e)<0||Number(i.kgCO2e)>100000))return JSON.stringify({status:'invalid_input'});
return JSON.stringify({status:'ok',unit:'kg CO2e',total:Math.round(items.reduce((n,i)=>n+Number(i.kgCO2e),0)*100)/100,notice:'Chỉ cộng các khoản có cùng đơn vị và phạm vi đo lường.'});
})(); } finally { console.log(JSON.stringify({event:'greensteps_n8n_tool_performance',tool:"carbon_summary",durationMs:Date.now()-toolStarted})); }
